_base.html:
{#
  Every template extends this. It sets the page, the fitting scale and the
  markup every section shares (see _parts.html); a template mostly supplies
  CSS, a header, and how the sections are arranged.

  Size everything in rem. 1rem is the body text size, and the whole resume
  shrinks with --s when it has to fit a page. Page margins stay put.
#}
<!DOCTYPE html>
<html lang="en" class="t-{{ template.id }} {{ page_size }}" style="--s: {{ scale }}; --base: {{ base_pt }}pt; --accent: {{ accent }};">
<head>
<meta charset="utf-8">
<title>{{ full_name or "Resume" }}</title>
<style>
{{ font_css | safe }}

@page { size: {{ page.css }}; margin: 0; }

:root {
  font-size: calc(var(--base) * var(--s));
  line-height: 1.3;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
  --page-w: {{ page.w }};
  --page-h: {{ page.h }};
  /* Page margins. The padding is repeated on every printed page. */
  --mt: 0.6in; --mb: 0.55in; --ms: 0.65in;
  --tint: color-mix(in srgb, var(--accent) 10%, white);
  --soft: color-mix(in srgb, var(--accent) 55%, white);
}

html, body { margin: 0; padding: 0; background: #fff; }
body { width: var(--page-w); color: #24282d; }

.sheet {
  box-sizing: border-box;
  width: var(--page-w);
  padding: var(--mt) var(--ms) var(--mb);
  -webkit-box-decoration-break: clone;
  box-decoration-break: clone;
}

*, *::before, *::after { box-sizing: border-box; }
h1, h2, h3, p, ul, dl, dd { margin: 0; padding: 0; }
a { color: inherit; text-decoration: none; }

.section { margin-top: 1.05rem; }
.section__title { font-size: 1.15rem; break-after: avoid; }
.entry, .edu, .skills__row { break-inside: avoid; }
.entry + .entry { margin-top: 0.7rem; }
.edu + .edu { margin-top: 0.45rem; }

.entry__head { display: flex; justify-content: space-between; align-items: baseline; gap: 1rem; }
.entry__title, .edu__degree { font-weight: 700; }
.entry__when { flex: none; white-space: nowrap; font-size: 0.95rem; color: #5a616b; }
.entry__type { white-space: nowrap; }
.entry__meta { font-size: 0.92rem; font-style: italic; color: #5a616b; margin-top: 0.1rem; }

.bullets { margin: 0.2rem 0 0 1.3rem; }
.bullets li { margin-bottom: 0.15rem; padding-left: 0.1rem; }

.summary { text-align: justify; hyphens: manual; }

.skills__row { display: flex; gap: 0.8rem; padding: 0.12rem 0; }
.skills__row dt { flex: none; width: 11.5rem; font-weight: 700; }
.skills__row dd { flex: 1; }
.skills-flat { display: grid; grid-template-columns: repeat(4, 1fr); gap: 0.15rem 0.8rem; list-style: none; }

.contact { display: flex; flex-wrap: wrap; align-items: center; }
.contact__item { display: inline-flex; align-items: center; gap: 0.3em; }
.ico { display: none; width: 0.95em; height: 0.95em; flex: none; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }

{% block css %}{% endblock %}
</style>
</head>
<body>
{% block body %}{% endblock %}
</body>
</html>

_parts.html:
{#
  Markup shared by every template. Templates import this `with context` and
  style the classes; they rarely need their own markup for a section.
#}

{% macro icon(kind) -%}
<svg class="ico" viewBox="0 0 24 24" aria-hidden="true">
{%- if kind == "phone" -%}<path d="M5 4h3.5l1.6 4-2.2 1.4a11 11 0 0 0 6.7 6.7l1.4-2.2 4 1.6V19a1.5 1.5 0 0 1-1.6 1.5A16.5 16.5 0 0 1 3.5 5.6 1.5 1.5 0 0 1 5 4z"/>
{%- elif kind == "email" -%}<rect x="3" y="5.5" width="18" height="13" rx="2"/><path d="M3.5 7l8.5 6 8.5-6"/>
{%- elif kind == "location" -%}<path d="M12 21s-6.5-6-6.5-11a6.5 6.5 0 0 1 13 0c0 5-6.5 11-6.5 11z"/><circle cx="12" cy="10" r="2.3"/>
{%- elif kind == "linkedin" -%}<rect x="3.5" y="3.5" width="17" height="17" rx="2.5"/><path d="M8 10.5V16M8 7.8v.1M11.5 16v-5.5M11.5 13c0-1.6 1-2.6 2.4-2.6s2.1 1 2.1 2.6v3"/>
{%- elif kind == "github" -%}<path d="M9 19c-4 1.3-4-2-6-2.5M15 21v-3.5a3 3 0 0 0-.9-2.4c3-.3 6-1.4 6-6.6a5 5 0 0 0-1.4-3.5 4.7 4.7 0 0 0-.1-3.5s-1.1-.3-3.6 1.4a12.4 12.4 0 0 0-6.4 0C6.1 1.2 5 1.5 5 1.5a4.7 4.7 0 0 0-.1 3.5A5 5 0 0 0 3.5 8.5c0 5.2 3 6.3 6 6.6a3 3 0 0 0-.9 2.4V21"/>
{%- else -%}<circle cx="12" cy="12" r="8.5"/><path d="M3.5 12h17M12 3.5c2.4 2.4 3.5 5.2 3.5 8.5s-1.1 6.1-3.5 8.5c-2.4-2.4-3.5-5.2-3.5-8.5s1.1-6.1 3.5-8.5z"/>
{%- endif -%}
</svg>
{%- endmacro %}

{% macro contact(sep="|") -%}
<p class="contact">
{% for c in contacts %}
<span class="contact__item contact__item--{{ c.kind }}">{{ icon(c.kind) }}{% if c.href %}<a href="{{ c.href }}">{{ c.text }}</a>{% else %}<span>{{ c.text }}</span>{% endif %}</span>
{% if not loop.last and sep %}<span class="contact__sep" aria-hidden="true">{{ sep }}</span>{% endif %}
{% endfor %}
</p>
{%- endmacro %}

{% macro when(start, end) -%}
{% if start and end %}{{ start }} &ndash; {{ end }}{% else %}{{ start or end or "" }}{% endif %}
{%- endmacro %}

{% macro languages_line() -%}
{% for l in languages %}{{ l.name }}{% if l.level %} ({{ l.level }}{% if l.note %}, {{ l.note }}{% endif %}){% endif %}{% if not loop.last %} &bull; {% endif %}{% endfor %}
{%- endmacro %}

{# One list of items, as bullets-joined text or as tags. #}
{% macro items(list, tags=false) -%}
{% if tags %}<span class="tags">{% for i in list %}<span class="tag">{{ i }}</span>{% endfor %}</span>
{% else %}{{ list | join(" • ") }}{% endif %}
{%- endmacro %}

{% macro title(name) -%}
<h2 class="section__title"><span>{{ titles[name] }}</span></h2>
{%- endmacro %}

{% macro summary_section() -%}
{% if summary %}
<section class="section section--summary">
  {{ title("summary") }}
  <p class="summary">{{ summary }}</p>
</section>
{% endif %}
{%- endmacro %}

{# Skills as a label / items table, or stacked groups when `stacked`. #}
{% macro skills_section(tags=false, stacked=false) -%}
{% if (skill_groups | length) or (skills | length) or (languages | length) %}
<section class="section section--skills">
  {{ title("skills") }}
  {% if (skill_groups | length) or (languages | length) %}
  <dl class="skills{% if stacked %} skills--stacked{% endif %}">
    {% for g in skill_groups %}
    <div class="skills__row"><dt>{{ g.label }}</dt><dd>{{ items(g["items"], tags) }}</dd></div>
    {% endfor %}
    {% if (skills | length) and (skill_groups | length) %}
    <div class="skills__row"><dt>Other</dt><dd>{{ items(skills, tags) }}</dd></div>
    {% endif %}
    {% if (skills | length) and not (skill_groups | length) %}
    <div class="skills__row skills__row--flat"><dd>{{ items(skills, tags) }}</dd></div>
    {% endif %}
    {% if (languages | length) %}
    <div class="skills__row skills__row--languages"><dt>Languages</dt><dd>{{ languages_line() }}</dd></div>
    {% endif %}
  </dl>
  {% else %}
  <ul class="skills-flat">{% for s in skills %}<li>{{ s }}</li>{% endfor %}</ul>
  {% endif %}
</section>
{% endif %}
{%- endmacro %}

{% macro experience_section() -%}
{% if (experience | length) %}
<section class="section section--experience">
  {{ title("experience") }}
  {% for job in experience %}
  <article class="entry">
    <div class="entry__head">
      <div class="entry__what">
        <span class="entry__title">{{ job.job_title }}</span>
        {%- if job.company %}<span class="entry__sep"> | </span><span class="entry__org">{{ job.company }}{% if job.location %}, {{ job.location }}{% endif %}{% if job.employment_type %} <span class="entry__type">&middot; {{ job.employment_type }}</span>{% endif %}</span>{% endif %}
      </div>
      <div class="entry__when">{{ when(job.start_date, job.end_date) }}</div>
    </div>
    {% if (job.highlights | length) %}
    <ul class="bullets">{% for p in job.highlights %}<li>{{ p }}</li>{% endfor %}</ul>
    {% endif %}
  </article>
  {% endfor %}
</section>
{% endif %}
{%- endmacro %}

{% macro projects_section() -%}
{% if (projects | length) %}
<section class="section section--projects">
  {{ title("projects") }}
  {% for p in projects %}
  <article class="entry">
    <div class="entry__head">
      <div class="entry__what">
        <span class="entry__title">{% if p.url %}<a href="{{ p.url }}">{{ p.name }}</a>{% else %}{{ p.name }}{% endif %}</span>
        {%- if p.role %}<span class="entry__sep"> | </span><span class="entry__org">{{ p.role }}{% if p.location %}, {{ p.location }}{% endif %}</span>{% endif %}
      </div>
      <div class="entry__when">{{ when(p.start_date, p.end_date) }}</div>
    </div>
    {% if (p.tech_stack | length) or p.url %}<div class="entry__meta">{{ p.tech_stack | join(" • ") }}{% if p.url %}{% if (p.tech_stack | length) %} • {% endif %}{{ p.url | shortlink }}{% endif %}</div>{% endif %}
    {% if (p.highlights | length) %}
    <ul class="bullets">{% for h in p.highlights %}<li>{{ h }}</li>{% endfor %}</ul>
    {% endif %}
  </article>
  {% endfor %}
</section>
{% endif %}
{%- endmacro %}

{% macro education_section() -%}
{% if (education | length) %}
<section class="section section--education">
  {{ title("education") }}
  {% for e in education %}
  <article class="edu">
    <div class="entry__head">
      <div class="edu__degree">{{ e.degree }}</div>
      <div class="entry__when">{{ e.graduation_date }}</div>
    </div>
    {% if e.institution %}<div class="edu__school">{{ e.institution }}{% if e.location %}, {{ e.location }}{% endif %}</div>{% endif %}
    {% if e.honors or e.grade %}<div class="edu__honors">{{ [e.honors, e.grade] | select | join(" · ") }}</div>{% endif %}
    {% if (e.highlights | length) %}
    <ul class="bullets">{% for h in e.highlights %}<li>{{ h }}</li>{% endfor %}</ul>
    {% endif %}
  </article>
  {% endfor %}
</section>
{% endif %}
{%- endmacro %}

{# A section you added: entries set like jobs, a list, or a paragraph. #}
{% macro extra_section(sid, tags=false) -%}
{% set sec = extras[sid] %}
<section class="section section--extra section--{{ sec.kind }} section--{{ sec.layout }}">
  {{ title(sid) }}
  {% if sec.layout == "entries" %}
  {% for e in sec["items"] %}
  <article class="entry">
    <div class="entry__head">
      <div class="entry__what">
        <span class="entry__title">{% if e.url %}<a href="{{ e.url }}">{{ e.title }}</a>{% else %}{{ e.title }}{% endif %}</span>
        {%- if e.subtitle %}<span class="entry__sep"> | </span><span class="entry__org">{{ e.subtitle }}{% if e.location %}, {{ e.location }}{% endif %}</span>{% endif %}
      </div>
      <div class="entry__when">{{ when(e.start_date, e.end_date) }}</div>
    </div>
    {% if e.url %}<div class="entry__meta">{{ e.url | shortlink }}</div>{% endif %}
    {% if (e.highlights | length) %}
    <ul class="bullets">{% for h in e.highlights %}<li>{{ h }}</li>{% endfor %}</ul>
    {% endif %}
  </article>
  {% endfor %}
  {% elif sec.layout == "list" %}
  <p class="extra-list">{{ items(sec["items"], tags) }}</p>
  {% else %}
  <p class="summary">{{ sec.text }}</p>
  {% endif %}
</section>
{%- endmacro %}

{% macro section(name, tags=false, stacked=false) -%}
{% if name == "summary" %}{{ summary_section() }}
{% elif name == "skills" %}{{ skills_section(tags, stacked) }}
{% elif name == "experience" %}{{ experience_section() }}
{% elif name == "projects" %}{{ projects_section() }}
{% elif name == "education" %}{{ education_section() }}
{% elif name in extras %}{{ extra_section(name, tags) }}
{% endif %}
{%- endmacro %}

{# The sections in your chosen order, optionally only some of them. #}
{% macro sections(only=none, exclude=none, tags=false, stacked=false) -%}
{% for name in order %}{% if (only == none or name in only) and (exclude == none or name not in exclude) %}{{ section(name, tags, stacked) }}{% endif %}{% endfor %}
{%- endmacro %}

banner.html:
{% extends "_base.html" %}
{% import "_parts.html" as parts with context %}

{% block css %}
:root { --mt: 0.5in; --mb: 0.5in; --ms: 0.6in; line-height: 1.32; }
body { font-family: "Archivo", "Segoe UI", sans-serif; color: #23262b; }

/* The band bleeds past the page margins to the paper's edges. */
.band {
  margin: calc(-1 * var(--mt)) calc(-1 * var(--ms)) 0;
  padding: 0.5in var(--ms) 0.95rem;
  background: var(--accent); color: #fff;
}
.header__name { font-size: 2.9rem; font-weight: 800; line-height: 0.95; letter-spacing: -0.02em; }
.header__title { margin-top: 0.35rem; font-size: 1.2rem; font-weight: 500; opacity: 0.88; }
.contact { margin-top: 0.7rem; gap: 0.25rem 1.1rem; font-size: 0.92rem; }
.contact__sep { display: none; }
.contact .ico { display: block; opacity: 0.8; }

.section { margin-top: 1.05rem; }
.section__title {
  font-size: 1.15rem; font-weight: 800; letter-spacing: -0.005em; color: var(--accent);
  padding-left: 0.55rem; border-left: 0.3rem solid var(--accent); line-height: 1.1; margin-bottom: 0.5rem;
}

.entry__title, .edu__degree { font-weight: 600; }
.entry__sep { color: var(--soft); }
.entry__org { color: #4d535b; }
.entry__when { font-weight: 500; color: var(--accent); }
.entry__meta { font-style: normal; font-size: 0.88rem; color: #5f666e; }
.edu__school { color: #4d535b; }
.edu__honors { color: #5f666e; font-size: 0.95rem; }
.bullets li::marker { color: var(--accent); }

.skills__row { align-items: baseline; padding: 0.18rem 0; }
.skills__row dt { width: 10rem; font-weight: 600; }
.tags { display: flex; flex-wrap: wrap; gap: 0.25rem; }
.tag { padding: 0.05rem 0.45rem; border-radius: 0.25rem; background: var(--tint); color: color-mix(in srgb, var(--accent) 80%, black); font-size: 0.92rem; }
{% endblock %}

{% block body %}
<main class="sheet">
  <header class="band">
    <h1 class="header__name">{{ full_name }}</h1>
    {% if pi.title %}<div class="header__title">{{ pi.title }}</div>{% endif %}
    {{ parts.contact(none) }}
  </header>
  {{ parts.sections(tags=true) }}
</main>
{% endblock %}

classic.html:
{% extends "_base.html" %}
{% import "_parts.html" as parts with context %}

{% block css %}
