column.html:
{% extends "_base.html" %}
{% import "_parts.html" as parts with context %}

{% block css %}
/* The sidebar colour is painted on the page itself so it runs edge to edge
   on every printed page, not just as far as the sidebar's content. */
:root { --side: 2.55in; --mt: 0.55in; --mb: 0.5in; --ms: 0; line-height: 1.32; }
html { background: linear-gradient(to right, var(--accent) 0 var(--side), #fff var(--side)); }
body { font-family: "IBM Plex Sans", "Segoe UI", sans-serif; color: #24282d; background: transparent; }

.sheet { display: grid; grid-template-columns: var(--side) 1fr; }

.side { padding: 0 1.55rem 0 0.5in; color: #fff; }
.main { padding: 0 0.55in 0 1.8rem; }

.header__name { font-size: 2.2rem; font-weight: 600; line-height: 1.05; letter-spacing: -0.01em; }
.header__name span { display: block; }
.header__title { margin-top: 0.5rem; font-size: 1rem; font-weight: 500; opacity: 0.85; }

.side .contact { flex-direction: column; align-items: flex-start; gap: 0.35rem; margin-top: 1.1rem; font-size: 0.88rem; }
.side .contact__sep { display: none; }
.side .ico { display: block; opacity: 0.75; }
.side .contact a, .side .contact span { overflow-wrap: anywhere; }

.side .section { margin-top: 1.4rem; }
.side .section__title {
  font-size: 0.85rem; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase;
  padding-bottom: 0.3rem; margin-bottom: 0.55rem; border-bottom: 1px solid rgba(255,255,255,0.35);
}
.side .skills__row { display: block; padding: 0; }
.side .skills__row + .skills__row { margin-top: 0.6rem; }
.side .skills__row dt { width: auto; font-weight: 600; font-size: 0.9rem; margin-bottom: 0.25rem; }
.side .skills__row dd { font-size: 0.88rem; }
.side .tags { display: flex; flex-wrap: wrap; gap: 0.25rem; }
.side .tag { padding: 0.1rem 0.4rem; border-radius: 0.2rem; background: rgba(255,255,255,0.14); }
.side .edu__degree { font-weight: 600; font-size: 0.92rem; }
.side .edu { display: flex; flex-direction: column; }
.side .edu .entry__head { display: contents; }
.side .edu .entry__when { order: 3; }
.side .edu .edu__honors { order: 4; }
.side .entry__when, .side .edu__school, .side .edu__honors { color: rgba(255,255,255,0.78); font-size: 0.86rem; }
.side .edu + .edu { margin-top: 0.7rem; }
.side .edu .bullets { order: 5; }
/* Added sections that land in the sidebar stack like education does. */
.side .entry__head { display: block; }
.side .entry__sep { display: none; }
.side .entry__title { font-weight: 600; font-size: 0.92rem; }
.side .entry__org, .side .entry__meta { display: block; font-style: normal; color: rgba(255,255,255,0.78); font-size: 0.86rem; }
.side .entry + .entry { margin-top: 0.7rem; }
.side .bullets { font-size: 0.86rem; }
.side .summary { text-align: left; font-size: 0.9rem; }

.main .section:first-child { margin-top: 0; }
.main .section { margin-top: 1.15rem; }
.main .section__title {
  font-size: 1.25rem; font-weight: 600; color: var(--accent);
  padding-bottom: 0.2rem; margin-bottom: 0.5rem; border-bottom: 1.5px solid var(--accent);
}
.main .entry__sep { display: none; }
.main .entry__org { display: block; color: var(--accent); font-weight: 500; }
.main .entry__title { font-weight: 600; }
.main .entry__when { color: #676e77; font-size: 0.9rem; }
.main .entry__meta { font-style: normal; font-size: 0.88rem; color: #676e77; }
.main .summary { text-align: left; }
{% endblock %}

{% block body %}
<main class="sheet">
  <aside class="side">
    <header class="header">
      <h1 class="header__name"><span>{{ pi.first_name }}</span><span>{{ pi.last_name }}</span></h1>
      {% if pi.title %}<div class="header__title">{{ pi.title }}</div>{% endif %}
      {{ parts.contact(none) }}
    </header>
    {{ parts.sections(only=side_sections, tags=true, stacked=true) }}
  </aside>
  <div class="main">
    {{ parts.sections(exclude=side_sections) }}
  </div>
</main>
{% endblock %}

compact.html:
{% extends "_base.html" %}
{% import "_parts.html" as parts with context %}

{# Tight spacing and small headings, for a long history that has to fit. #}

{% block css %}
:root { --mt: 0.45in; --mb: 0.42in; --ms: 0.55in; line-height: 1.26; }
body { font-family: "Source Sans 3", "Segoe UI", sans-serif; color: #24282d; }

