.header__title { margin-top: 0.2rem; font-size: 1.1rem; font-weight: 600; color: var(--accent); }
.contact { flex: none; max-width: 55%; justify-content: flex-end; gap: 0.1rem 0.9rem; font-size: 0.9rem; color: #444a52; }
.contact__sep { display: none; }
.contact .ico { display: block; color: var(--accent); }

.section { margin-top: 0.7rem; }
.section__title {
  font-size: 0.95rem; font-weight: 700; letter-spacing: 0.09em; text-transform: uppercase; color: var(--accent);
  padding-bottom: 0.1rem; margin-bottom: 0.3rem; border-bottom: 1px solid var(--soft);
}
.entry + .entry { margin-top: 0.45rem; }
.edu + .edu { margin-top: 0.3rem; }
.entry__title, .edu__degree { font-weight: 700; }
.entry__sep { color: var(--soft); }
.entry__org { font-weight: 600; color: #444a52; }
.entry__when { font-size: 0.9rem; font-weight: 600; color: #5d646c; }
.entry__meta { font-size: 0.88rem; margin-top: 0; }
.edu__school { color: #444a52; }
.edu__honors { font-size: 0.92rem; color: #5d646c; }
.bullets { margin-top: 0.1rem; }
.bullets li { margin-bottom: 0.05rem; }
.bullets li::marker { color: var(--accent); }
